-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann das Betriebsverfassungsgesetz ohne Betriebsrat gelten?', 2, '[{"text": "Ja", "correct": true, "because": "Gilt für Betriebe generell"}, {"text": "Nein", "correct": false, "because": "Betriebsrat optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss mein Betrieb das Betriebsverfassungsgesetz beachten?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht ab 5 Mitarbeitern"}, {"text": "Nein", "correct": false, "because": "Gesetzlich bindend"}]'),
('00000000-0000-0000-0000-000000000000', 'Gilt das Betriebsverfassungsgesetz auch für Azubis?', 2, '[{"text": "Ja", "correct": true, "because": "Alle Mitarbeiter eingeschlossen"}, {"text": "Nein", "correct": false, "because": "Azubis sind Arbeitnehmer"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte das Betriebsverfassungsgesetz meine Arbeitszeit regeln?', 2, '[{"text": "Ja", "correct": true, "because": "Mitbestimmung bei Arbeitszeiten"}, {"text": "Nein", "correct": false, "because": "ArbZG ergänzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Schützt das Betriebsverfassungsgesetz meine Rechte?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert Mitbestimmung"}, {"text": "Nein", "correct": false, "because": "Rechte durch Betriebsrat"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann mein Chef das Betriebsverfassungsgesetz ignorieren?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzlich bindend"}, {"text": "Ja", "correct": false, "because": "Verstoß strafbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Betriebsverfassungsgesetz nur für große Betriebe?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt ab 5 Mitarbeitern"}, {"text": "Ja", "correct": false, "because": "Unabhängig von Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich laut Betriebsverfassungsgesetz den Betriebsrat wählen?', 2, '[{"text": "Ja", "correct": true, "because": "Wahlrecht für alle"}, {"text": "Nein", "correct": false, "because": "Azubis wahlberechtigt"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Betriebsverfassungsgesetzes?', 2, '[{"text": "Mitbestimmung fördern", "correct": true, "because": "Kern des Gesetzes"}, {"text": "Steuern regeln", "correct": false, "because": "Kein Bezug"}, {"text": "Urlaub festlegen", "correct": false, "because": "Anderes Gesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, das BetrVG gilt nicht für uns. Wann stimmt das?', 3, '[{"text": "Unter 5 Mitarbeitern", "correct": true, "because": "Schwelle für Geltung"}, {"text": "Immer", "correct": false, "because": "Gilt ab 5"}, {"text": "Nur für Azubis", "correct": false, "because": "Alle betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht gibt mir das Betriebsverfassungsgesetz?', 2, '[{"text": "Betriebsrat wählen", "correct": true, "because": "Mitbestimmung"}, {"text": "Gehalt erhöhen", "correct": false, "because": "Tarifsache"}, {"text": "Urlaub bestimmen", "correct": false, "because": "Betriebssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, was das BetrVG regelt. Was sage ich?', 3, '[{"text": "Rechte des Betriebsrats", "correct": true, "because": "Hauptfokus"}, {"text": "Nur Prüfungen", "correct": false, "because": "Zu eng"}, {"text": "Nur Vergütung", "correct": false, "because": "Zu spezifisch"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was regelt das Betriebsverfassungsgesetz?', 4, '[{"text": "Betriebsratswahl", "correct": true, "because": "Grundlage"}, {"text": "Mitbestimmung", "correct": true, "because": "Kernaufgabe"}, {"text": "Arbeitsschutz", "correct": true, "because": "Mitbestimmungsrecht"}, {"text": "Steuerpflicht", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte gibt das BetrVG dem Betriebsrat?', 3, '[{"text": "Anhören bei Kündigungen", "correct": true, "because": "Pflicht"}, {"text": "Mitbestimmung bei Arbeitszeiten", "correct": true, "because": "§87 BetrVG"}, {"text": "Information über Personalplanung", "correct": true, "because": "Transparenz"}, {"text": "Gehalt festlegen", "correct": false, "because": "Tarifsache"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Konflikte im Betrieb. Was sagt das BetrVG?', 3, '[{"text": "Betriebsrat wird beteiligt", "correct": true, "because": "Mitbestimmung"}, {"text": "Schlichtung möglich", "correct": true, "because": "Konfliktlösung"}, {"text": "Arbeitsschutz gewährleisten", "correct": true, "because": "Pflicht"}, {"text": "Betrieb schließen", "correct": false, "because": "Keine Befugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten legt das BetrVG dem Betrieb auf?', 4, '[{"text": "Betriebsrat informieren", "correct": true, "because": "Transparenz"}, {"text": "Mitbestimmung zulassen", "correct": true, "because": "Gesetzlich"}, {"text": "Anhören bei Kündigungen", "correct": true, "because": "Vorgeschrieben"}, {"text": "Azubis entlassen", "correct": false, "because": "Kein Recht"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das BetrVG regelt die Betriebsratswahl. b) Es gilt nur für Azubis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wahl ja, alle betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BetrVG gibt Mitbestimmungsrechte. b) Es regelt meine Prüfungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mitbestimmung ja, Prüfungen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BetrVG schützt bei Kündigungen. b) Es ist nur für große Betriebe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kündigung ja, Größe egal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BetrVG erlaubt einen Betriebsrat. b) Es regelt meine Vergütung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Betriebsrat ja, Vergütung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

